"use client"

import * as React from "react"
import { ChevronDown, ChevronLeft, LogOut, Menu } from "lucide-react"

import { cn } from "@/registry/naf/lib/utils"

// هيكل ناف الموحّد: شريط جانبي في جهة البداية، وترويسة تحمل فتات المسار
// وقائمة الحساب، وحاضن محتوى بعرض مسجَّل.
//
// المكوّن لا يحمل أنماطه: كلها في naf-app-shell.css. والسبب أن المنصات
// الخمس ليست على تقنية واحدة — ثلاثٌ منها تكتب CSS خاماً أو HTML ثابتاً
// ولا تستهلك React أصلاً. فلو حمل المكوّن أصنافه لَانقسم الهيكل نسختين
// تتباعدان، وهو الانحراف الذي وقع أوّل مرّة.
//
// التنقّل لا يُفرض هنا: كل منصة على موجّهها (react-router أو next/link)،
// فتُصدَّر `navLinkClassName` وتَبني المنصة رابطها بموجّهها. فرضُ موجّهٍ
// واحد كان سيمنع المنصات الثلاث الباقية من استهلاك الهيكل.
//
// المصطلحات من naf-terms.md والأيقونات من naf-icons.md.

const TERMS = {
  menu: "القائمة",
  breadcrumb: "مسار التنقّل",
  account: "الحساب",
  signOut: "تسجيل الخروج",
  appearance: "المظهر",
  /** حسابٌ بلا اسم مسجَّل. لا البريد مكانه — naf-terms.md §١٠. */
  noName: "مستخدم",
}

/* ── حالة الدرج ── */

interface ShellContextValue {
  open: boolean
  setOpen: (value: boolean) => void
}

const ShellContext = React.createContext<ShellContextValue | null>(null)

export function useShell(): ShellContextValue {
  const ctx = React.useContext(ShellContext)
  if (!ctx) throw new Error("useShell تُستدعى داخل AppShell وحدها")
  return ctx
}

export interface AppShellProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * ارتفاع الشاشة لا ارتفاع المحتوى — للمنصات التي تمرّر شاشاتها
   * بنفسها (`AppContent flush`). تركُها يجعل الصفحة تمتدّ بطول محتواها.
   */
  fixed?: boolean
}

export const AppShell = React.forwardRef<HTMLDivElement, AppShellProps>(
  ({ fixed = false, className, children, ...props }, ref) => {
    const [open, setOpen] = React.useState(false)

    // Esc يغلق الدرج. الحجاب يُغلقه بالنقر، ولوحة المفاتيح تحتاج مخرجاً
    // مثله — ودرجٌ لا يُغلق إلا بالفأرة يحبس من لا يستعملها.
    React.useEffect(() => {
      if (!open) return
      const onKey = (e: KeyboardEvent) => {
        if (e.key === "Escape") setOpen(false)
      }
      document.addEventListener("keydown", onKey)
      return () => document.removeEventListener("keydown", onKey)
    }, [open])

    // تمرير الخلفية يُوقف والدرج مفتوح: بدونه يمرّر الإصبعُ الصفحةَ تحت
    // الدرج فيبدو أن اللمس أخطأ هدفه.
    React.useEffect(() => {
      if (!open) return
      const previous = document.body.style.overflow
      document.body.style.overflow = "hidden"
      return () => {
        document.body.style.overflow = previous
      }
    }, [open])

    return (
      <ShellContext.Provider value={{ open, setOpen }}>
        <div
          ref={ref}
          className={cn("naf-shell", fixed && "naf-shell--fixed", className)}
          {...props}
        >
          {children}
        </div>
      </ShellContext.Provider>
    )
  }
)
AppShell.displayName = "AppShell"

/* ── الشريط الجانبي ── */

export const Sidebar = React.forwardRef<HTMLElement, React.HTMLAttributes<HTMLElement>>(
  ({ className, children, ...props }, ref) => {
    const { open } = useShell()
    return (
      <aside
        ref={ref}
        id="naf-sidebar"
        className={cn("naf-sidebar", open && "is-open", className)}
        {...props}
      >
        {children}
      </aside>
    )
  }
)
Sidebar.displayName = "Sidebar"

export const SidebarHeader = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn("naf-sidebar-header", className)} {...props} />
  )
)
SidebarHeader.displayName = "SidebarHeader"

export const SidebarNav = React.forwardRef<HTMLElement, React.HTMLAttributes<HTMLElement>>(
  ({ className, ...props }, ref) => (
    <nav ref={ref} className={cn("naf-sidebar-nav", className)} {...props} />
  )
)
SidebarNav.displayName = "SidebarNav"

export const SidebarFooter = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn("naf-sidebar-footer", className)} {...props} />
  )
)
SidebarFooter.displayName = "SidebarFooter"

/** صنف رابط التنقّل. المنصة تبنيه بموجّهها وتمرّر حالة النشاط. */
export function navLinkClassName(isActive?: boolean, className?: string): string {
  return cn("naf-nav-link", isActive && "is-active", className)
}

/* ── الترويسة ── */

export const AppHeader = React.forwardRef<HTMLElement, React.HTMLAttributes<HTMLElement>>(
  ({ className, ...props }, ref) => (
    <header ref={ref} className={cn("naf-header", className)} {...props} />
  )
)
AppHeader.displayName = "AppHeader"

export const HeaderStart = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn("naf-header-start", className)} {...props} />
  )
)
HeaderStart.displayName = "HeaderStart"

export const HeaderEnd = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn("naf-header-end", className)} {...props} />
  )
)
HeaderEnd.displayName = "HeaderEnd"

/** زرّ القائمة — لا يظهر إلا دون نقطة الانكسار، والأنماط تتكفّل بذلك. */
export function MenuButton({ className, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement>) {
  const { open, setOpen } = useShell()
  return (
    <button
      type="button"
      className={cn("naf-icon-btn naf-menu-btn", className)}
      aria-label={TERMS.menu}
      aria-expanded={open}
      aria-controls="naf-sidebar"
      onClick={() => setOpen(!open)}
      {...props}
    >
      <Menu size={20} aria-hidden="true" />
    </button>
  )
}

/** الحجاب. يُركَّب مرّة واحدة داخل AppShell. */
export function ShellBackdrop() {
  const { open, setOpen } = useShell()
  return (
    <div
      className={cn("naf-backdrop", open && "is-open")}
      onClick={() => setOpen(false)}
      aria-hidden="true"
    />
  )
}

export interface Crumb {
  label: string
  href?: string
}

/** فتات المسار. الفاصل `ChevronLeft` من الخريطة، ويُقلب في LTR. */
export function Breadcrumbs({ items, className }: { items: Crumb[]; className?: string }) {
  if (items.length === 0) return null
  return (
    <nav className={cn("naf-crumbs", className)} aria-label={TERMS.breadcrumb}>
      {items.map((crumb, index) => {
        const isLast = index === items.length - 1
        return (
          <React.Fragment key={`${crumb.label}-${index}`}>
            <ChevronLeft size={16} className="naf-crumb-sep" aria-hidden="true" />
            {crumb.href && !isLast ? (
              <a href={crumb.href} className="naf-crumb">
                {crumb.label}
              </a>
            ) : (
              <span
                className={cn("naf-crumb", isLast && "is-current")}
                aria-current={isLast ? "page" : undefined}
              >
                {crumb.label}
              </span>
            )}
          </React.Fragment>
        )
      })}
    </nav>
  )
}

/* ── قائمة الحساب ── */

export interface AccountMenuItem {
  label: string
  icon?: React.ReactNode
  href?: string
  onSelect?: () => void
}

export interface AccountMenuProps {
  /**
   * اسم صاحب الحساب كما هو مسجَّل في المركز — لا بريده ولا درجته.
   *
   * يُمرَّر كما هو ولو كان فارغاً: البديل هنا لا في المنصة، وإلا اختار
   * كلٌّ بديله. وقع فعلاً — منصتان وضعتا البريد مكان الاسم الغائب،
   * والبريد معرّف دخول لا يُخاطَب به أحد (naf-terms.md §١٠).
   */
  name?: string | null
  email?: string
  /** درجة الصلاحية كما هي مسجّلة في naf-terms.md — لا تُصاغ هنا. */
  role?: string
  /** بنود تخصّ المنصة، بأيقوناتها المسجّلة. تُعرض فوق الخروج. */
  items?: AccountMenuItem[]
  /** مُبدِّل المظهر المسجَّل. يُمرَّر لا يُبنى هنا. */
  appearance?: React.ReactNode
  onLogout: () => void
  className?: string
}

/** أول حرف من الاسم، بديلاً عن صورة غائبة. */
function initial(name: string): string {
  return Array.from(name.trim())[0] ?? "؟"
}

/**
 * قائمة الحساب: الهوية والمظهر وبنود المنصة ثم تسجيل الخروج.
 *
 * الخروج داخل القائمة لا زرّاً ظاهراً: زرٌّ منفرد بجوار الإشعارات يُنقر
 * سهواً، وهو إجراء لا رجعة فيه في الجلسة. والقائمة تجمع أوامر الحساب في
 * موضع واحد فلا يبحث القارئ عنها في خمس منصات في خمسة أماكن.
 */
export function AccountMenu({
  name,
  email,
  role,
  items = [],
  appearance,
  onLogout,
  className,
}: AccountMenuProps) {
  const [open, setOpen] = React.useState(false)
  const wrapRef = React.useRef<HTMLDivElement>(null)
  const triggerRef = React.useRef<HTMLButtonElement>(null)

  // البديل يُحسم هنا مرّة واحدة للمنصات الخمس
  const shown = name?.trim() || TERMS.noName

  // النقر خارج القائمة يغلقها، وEsc يغلقها ويعيد التركيز إلى زرّها —
  // وإلا ضاع التركيز في أوّل الصفحة بعد الإغلاق بلوحة المفاتيح.
  React.useEffect(() => {
    if (!open) return
    const onPointerDown = (e: PointerEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) setOpen(false)
    }
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return
      setOpen(false)
      triggerRef.current?.focus()
    }
    document.addEventListener("pointerdown", onPointerDown)
    document.addEventListener("keydown", onKey)
    return () => {
      document.removeEventListener("pointerdown", onPointerDown)
      document.removeEventListener("keydown", onKey)
    }
  }, [open])

  return (
    <div ref={wrapRef} className={cn("naf-account-wrap", className)}>
      <button
        ref={triggerRef}
        type="button"
        className="naf-account"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-label={TERMS.account}
        onClick={() => setOpen((v) => !v)}
      >
        <span className="naf-avatar" aria-hidden="true">
          {initial(shown)}
        </span>
        {/* الاسم وحده في الترويسة — لا الدور ولا البريد.
            كانت الخمس تعرض ثلاثة أشياء مختلفة في هذا الموضع: اثنتان
            الاسمَ ودرجتَه، واثنتان البريد، وواحدة البريد ودرجته. فمن
            يفتح منصتين يرى نفسه شخصين. والدرجة والبريد لم يُحذفا —
            انتقلا إلى صدر القائمة، حيث يُطلبان عن قصد. */}
        <span className="naf-account-text">
          <span className="naf-account-name">{shown}</span>
        </span>
        <ChevronDown size={16} className="naf-account-chevron" aria-hidden="true" />
      </button>

      {open ? (
        <div className="naf-account-menu" role="menu">
          {/* صدر القائمة يحمل الهوية كاملة: الاسم ثم الدرجة ثم البريد.
              هنا موضعها لا في الترويسة — يُقرأ عند طلبه. */}
          <div className="naf-account-menu-header">
            <div className="naf-account-name">{shown}</div>
            {role ? <div className="naf-account-role">{role}</div> : null}
            {/* البريد يخلط لاتينياً بعربية الواجهة، فيُعزل اتجاهه */}
            {email ? (
              <bdi className="naf-account-menu-email">{email}</bdi>
            ) : null}
          </div>

          {appearance ? (
            <>
              <hr className="naf-account-menu-sep" />
              <div className="naf-account-menu-appearance">
                <div className="naf-account-menu-email">{TERMS.appearance}</div>
                {appearance}
              </div>
            </>
          ) : null}

          {items.length > 0 ? <hr className="naf-account-menu-sep" /> : null}
          {items.map((item) =>
            item.href ? (
              <a
                key={item.label}
                href={item.href}
                role="menuitem"
                className="naf-account-menu-item"
                onClick={() => setOpen(false)}
              >
                {item.icon}
                <span>{item.label}</span>
              </a>
            ) : (
              <button
                key={item.label}
                type="button"
                role="menuitem"
                className="naf-account-menu-item"
                onClick={() => {
                  setOpen(false)
                  item.onSelect?.()
                }}
              >
                {item.icon}
                <span>{item.label}</span>
              </button>
            )
          )}

          <hr className="naf-account-menu-sep" />
          <button
            type="button"
            role="menuitem"
            className="naf-account-menu-item"
            onClick={() => {
              setOpen(false)
              onLogout()
            }}
          >
            <LogOut size={20} aria-hidden="true" />
            <span>{TERMS.signOut}</span>
          </button>
        </div>
      ) : null}
    </div>
  )
}

/* ── المحتوى ── */

export interface AppContentProps extends React.HTMLAttributes<HTMLElement> {
  /** شاشة تدير حشوها وتمريرها بنفسها — محادثة أو محرّر أو لوح. */
  flush?: boolean
}

export const AppContent = React.forwardRef<HTMLElement, AppContentProps>(
  ({ flush = false, className, ...props }, ref) => (
    <main
      ref={ref}
      className={cn("naf-content", flush && "naf-content--flush", className)}
      {...props}
    />
  )
)
AppContent.displayName = "AppContent"

export const AppMain = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn("naf-main", className)} {...props} />
  )
)
AppMain.displayName = "AppMain"

export type PageWidth = "narrow" | "default" | "wide" | "full"

const PAGE_WIDTH_CLASS: Record<PageWidth, string> = {
  narrow: "naf-page--narrow",
  default: "",
  wide: "naf-page--wide",
  full: "naf-page--full",
}

export interface PageProps extends React.HTMLAttributes<HTMLDivElement> {
  /** درجة العرض من الرموز المسجّلة — لا رقم يُكتب في الشاشة. */
  width?: PageWidth
}

/** حاضن الصفحة. يوسّط المحتوى ويحدّ عرضه بدرجة مسجّلة. */
export const Page = React.forwardRef<HTMLDivElement, PageProps>(
  ({ width = "default", className, ...props }, ref) => (
    <div ref={ref} className={cn("naf-page", PAGE_WIDTH_CLASS[width], className)} {...props} />
  )
)
Page.displayName = "Page"

/* ============================================================
   هيكل ناف الموحّد — شريط جانبي وترويسة وحاضن محتوى.

   لماذا CSS لا Tailwind وحدها: المنصات الخمس ليست على تقنية واحدة.
   الاستبانات والمحاسب على Tailwind، والتسويق ومستشار ناف يكتبان CSS
   خاماً، ومولّد التقارير صفحات HTML ثابتة بلا بناء أصلاً. فلو كُتب
   الهيكل أصنافَ Tailwind لَما استهلكه إلا اثنان، وأعاد الثلاثة كتابته
   بأيديهم — وهو الانحراف نفسه الذي وقع أوّل مرّة: شريط جانبي بعرض 260
   في التسويق و264 في المحاسب و300 في مستشار ناف، وثلاث نقاط انكسار
   مختلفة، وأربع صور لزرّ الخروج.

   فالهيكل ملفٌّ واحد تستورده المنصات الخمس كما هو، والمكوّن
   `app-shell.tsx` يُصدر هذه الأصناف نفسها لمن يكتب React. لا نسختان.

   كل القيم رموز من naf-theme.css. والخصائص كلها منطقية الاتجاه
   (inline-start / inline-end) فالهيكل يعمل في RTL وLTR بلا فرع.
   ============================================================ */

/* نقطة الانكسار الوحيدة: 900 بكسل.

   مكتوبة رقماً هنا لأن @media لا تقرأ var() — لا متصفّح يحلّ خاصية
   مخصّصة داخل استعلام وسائط، وهذا قيد اللغة لا اختيار.

   وهذا الملف مصدرها: الهيكل نفسه — الشريط والدرج والحجاب وزرّ القائمة
   وقائمة الحساب — لا يُعاد انكساره في منصة أبداً.

   ومنصةٌ لها تخطيطها الخاص (شبكةُ بطاقات تنطوي إلى عمود، جدولٌ يتمرّر)
   تحتاج أن توافق النقطة نفسها، فتكتب `@media (width < 900px)` وتشير إلى
   هذا السطر في تعليقها. الرقم واحد في المنصات الخمس، وتغييره يبدأ هنا
   ثم يُنقل. وما استغنى عن الاستعلام يستهلك `.naf-only-mobile` و
   `.naf-only-desktop` أدناه، أو يسأل `matchMedia('(width < 900px)')`.

   والرقم 900 لا 768: الشريط 280 بكسل، وعند 768 يبقى للمحتوى 488 —
   وهو أضيق من أن يحمل جدولاً أو نموذجاً من عمودين. */

.naf-shell {
  display: flex;
  min-height: 100dvh;
  background: var(--background);
  color: var(--foreground);
}

/* هيكل بارتفاع الشاشة لا بارتفاع محتواه — للمنصات التي تدير شاشاتها
   تمريرها بنفسها (`naf-content--flush`). بدونه تمتدّ الصفحة بطول
   المحادثة ويظهر شريط تمرير للصفحة كلّها فوق شريط تمرير اللوح. */
.naf-shell--fixed {
  height: 100dvh;
  overflow: hidden;
}

/* ── الشريط الجانبي ── */

.naf-sidebar {
  width: var(--shell-sidebar);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  background: var(--sidebar);
  color: var(--sidebar-foreground);
  border-inline-end: 1px solid var(--sidebar-border);
  position: sticky;
  top: 0;
  height: 100dvh;
  /* الشريط يملأ الارتفاع كلَّه، فطرفاه يقعان تحت النتوء وتحت شريط
     الإيماءات معاً حين تُفتح الصفحة تطبيقاً. */
  padding-block-start: env(safe-area-inset-top);
  padding-block-end: env(safe-area-inset-bottom);
}

.naf-sidebar-header {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-4);
  border-bottom: 1px solid var(--sidebar-border);
  min-height: var(--shell-header);
}

.naf-sidebar-brand-name {
  font-size: var(--text-base);
  font-weight: 700;
  line-height: var(--text-base--line-height);
}

.naf-sidebar-brand-sub {
  font-size: var(--text-xs);
  line-height: var(--text-xs--line-height);
  /* على سطح --sidebar لا --card: الرمز المخصّص للسطح هو ما يقيس تباينه. */
  color: color-mix(in oklab, var(--sidebar-foreground) 70%, transparent);
}

.naf-sidebar-nav {
  flex: 1;
  overflow-y: auto;
  padding: var(--space-3);
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.naf-nav-section {
  padding: var(--space-3) var(--space-3) var(--space-2);
  font-size: var(--text-xs);
  line-height: var(--text-xs--line-height);
  font-weight: 600;
  color: color-mix(in oklab, var(--sidebar-foreground) 70%, transparent);
}

.naf-nav-link {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-lg);
  font-size: var(--text-sm);
  line-height: var(--text-sm--line-height);
  font-weight: 600;
  color: var(--sidebar-foreground);
  text-decoration: none;
  background: none;
  border: none;
  cursor: pointer;
  text-align: start;
  width: 100%;
  transition: background-color 0.12s, color 0.12s;
}

.naf-nav-link:hover {
  background: var(--sidebar-accent);
  color: var(--sidebar-accent-foreground);
}

.naf-nav-link.is-active {
  background: var(--sidebar-primary);
  color: var(--sidebar-primary-foreground);
}

/* الأيقونة لا تنكمش حين يطول النصّ */
.naf-nav-link > svg {
  flex-shrink: 0;
}

.naf-sidebar-footer {
  padding: var(--space-4);
  border-top: 1px solid var(--sidebar-border);
  font-size: var(--text-xs);
  line-height: var(--text-xs--line-height);
  color: color-mix(in oklab, var(--sidebar-foreground) 70%, transparent);
}

/* ── المنطقة الرئيسية ── */

/* min-width: 0 لازمة لا زينة: عنصر flex عرضه الأدنى محتواه، فجدولٌ
   عريض داخله يدفع الهيكل كلّه فيتجاوز عرض الشاشة بدل أن يتمرّر. */
.naf-main {
  flex: 1;
  min-width: 0;
  /* min-height: 0 للسبب نفسه في المحور الرأسي — يحتاجها الابن الذي
     يمرّر نفسه (`naf-content--flush`) ولا تضرّ غيره. */
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* الترويسة ملاصقةٌ لأعلى الشاشة، وشريط الحالة شفّاف في تطبيق الشاشة
   الرئيسية — فتمتدّ الصفحة تحته. الحشو العلويّ من الجهاز، والارتفاع يزيد
   بمقداره فلا يُضغط المحتوى بدل أن يُزاح.

   و`env()` تساوي صفراً خارج التطبيق المضاف، فالسطران لا يفعلان شيئاً في
   المتصفّح العادي ولا على سطح المكتب. */
.naf-header {
  height: calc(var(--shell-header) + env(safe-area-inset-top));
  padding-block-start: env(safe-area-inset-top);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding-inline: var(--space-4);
  border-bottom: 1px solid var(--border);
  background: color-mix(in oklab, var(--background) 85%, transparent);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 20;
}

.naf-header-start,
.naf-header-end {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 0;
}

/* ── فتات المسار ── */

.naf-crumbs {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 0;
  font-size: var(--text-sm);
  line-height: var(--text-sm--line-height);
}

/* القصّ على كل فتاتة مع min-width: 0 على الحاضن: مسارٌ طويل يُقصَّر
   بدل أن يدفع الترويسة فتتجاوز الشاشة عند 375 بكسل. */
.naf-crumb {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted-foreground);
  text-decoration: none;
}

.naf-crumb:hover {
  color: var(--foreground);
}

.naf-crumb.is-current {
  color: var(--foreground);
  font-weight: 600;
}

.naf-crumb-sep {
  flex-shrink: 0;
  color: var(--muted-foreground);
}

/* ── الأزرار الأيقونية في الترويسة ── */

.naf-icon-btn {
  width: var(--space-9);
  height: var(--space-9);
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: var(--radius-md);
  border: none;
  /* صفر صراحةً: منصةٌ تنسّق `button` المجرّد تحقن حشواً هنا فينتفخ الزرّ
     عن مقاسه. وقع في مولّد التقارير — حشو 0.85rem على كل زرّ. */
  padding: 0;
  background: none;
  color: var(--muted-foreground);
  cursor: pointer;
  transition: background-color 0.12s, color 0.12s;
}

.naf-icon-btn:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}

/* زرّ القائمة — لا وجود له فوق نقطة الانكسار */
.naf-menu-btn {
  display: none;
}

/* ── قائمة الحساب ── */

.naf-account-wrap {
  position: relative;
  flex-shrink: 0;
}

.naf-account {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-lg);
  border: none;
  background: none;
  color: var(--foreground);
  cursor: pointer;
  max-width: 100%;
  transition: background-color 0.12s;
}

.naf-account:hover {
  background: var(--accent);
}

.naf-avatar {
  width: var(--space-9);
  height: var(--space-9);
  flex-shrink: 0;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: var(--text-sm);
  font-weight: 700;
  /* نصّ على خلفية soft يأخذ الرمز strong لا الأساسي — §٦ */
  background: var(--primary-soft);
  color: var(--primary-strong);
}

/* الاسم والدرجة يختفيان دون نقطة الانكسار: الأحرف الأولى تكفي
   للتعرّف، والترويسة على 375 بكسل لا تتّسع لسطرين ونصّ. */
.naf-account-text {
  display: none;
  min-width: 0;
  text-align: start;
}

/* سطران لا سطر: كلاهما span، والافتراضي inline — فيلتصق البريد بالدرجة
   ويُقرآن كلمةً واحدة («fahad@naf.saمسؤول النظام»). ظهر في التصيير. */
.naf-account-name {
  display: block;
  font-size: var(--text-sm);
  line-height: var(--text-sm--line-height);
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.naf-account-role {
  display: block;
  font-size: var(--text-xs);
  line-height: var(--text-xs--line-height);
  color: var(--muted-foreground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.naf-account-chevron {
  flex-shrink: 0;
  color: var(--muted-foreground);
  transition: transform 0.15s;
}

.naf-account[aria-expanded='true'] .naf-account-chevron {
  transform: rotate(180deg);
}

.naf-account-menu {
  position: absolute;
  inset-inline-end: 0;
  top: calc(100% + var(--space-2));
  /* العرض من المحتوى لا رقماً مكتوباً — وسقفُه أضيق الشاشة دائماً */
  width: max-content;
  max-width: min(var(--page-narrow), calc(100vw - var(--space-6)));
  background: var(--popover);
  color: var(--popover-foreground);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: var(--space-2);
  z-index: 30;
}

.naf-account-menu-header {
  padding: var(--space-2) var(--space-3);
}

.naf-account-menu-email {
  font-size: var(--text-xs);
  line-height: var(--text-xs--line-height);
  color: var(--muted-foreground);
  overflow: hidden;
  text-overflow: ellipsis;
}

.naf-account-menu-sep {
  height: 1px;
  background: var(--border);
  margin: var(--space-2) 0;
  border: none;
}

.naf-account-menu-item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  width: 100%;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  border: none;
  background: none;
  color: var(--foreground);
  font-size: var(--text-sm);
  line-height: var(--text-sm--line-height);
  font-weight: 500;
  text-align: start;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 0.12s;
}

.naf-account-menu-item:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}

.naf-account-menu-item > svg {
  flex-shrink: 0;
  color: var(--muted-foreground);
}

/* الخروج إجراء مغادرة لا هدم: يأخذ لون النصّ العادي، وتمييزه باللون
   المدمّر يجعله يُقرأ حذفاً. §٦ — اللون للحالة لا للتشديد. */

/* مجموعة المظهر داخل القائمة تُعرض صفّاً واحداً */
.naf-account-menu-appearance {
  padding: var(--space-2) var(--space-3);
}

/* ── المحتوى ── */

.naf-content {
  flex: 1;
  min-width: 0;
  padding: var(--space-6) var(--space-4);
}

/* شاشة تدير تمريرها بنفسها — محادثة أو محرّر أو لوح.

   الحشو والتمرير من الحاضن يكسرانها: لوحُ المحادثة يملأ الارتفاع
   ويمرّر رسائله وحده، فحشوٌ حوله يزيح حقل الكتابة عن أسفل الشاشة،
   وتمريرٌ ثانٍ فوق تمريره يعطي شريطَي تمرير متداخلين.

   min-height: 0 لازمة: عنصر flex ارتفاعه الأدنى محتواه، فبدونها
   يمتدّ اللوح بطول رسائله بدل أن يمرّرها داخل حدوده. */
.naf-content--flush {
  padding: 0;
  overflow: hidden;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* حاضن الصفحة — الدرجة تُختار بصنف لا برقم يُكتب في الشاشة */
.naf-page {
  width: 100%;
  margin-inline: auto;
  max-width: var(--page-default);
}

.naf-page--narrow { max-width: var(--page-narrow); }
.naf-page--wide { max-width: var(--page-wide); }
.naf-page--full { max-width: none; }

/* ── الحجاب والدرج ── */

.naf-backdrop {
  display: none;
}

/* ── إظهار وإخفاء حسب المقاس ── */

.naf-only-mobile { display: none; }

/* ── التركيز ──
   حلقة ظاهرة على كل عنصر تفاعلي في الهيكل. §٤ تجعلها إلزامية،
   ووضعها هنا يعني أن منصةً لا تنساها. */

.naf-nav-link:focus-visible,
.naf-icon-btn:focus-visible,
.naf-account:focus-visible,
.naf-account-menu-item:focus-visible,
.naf-crumb:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

/* ============================================================
   دون 900 بكسل: الشريط يصير درجاً
   ============================================================ */

@media (width < 900px) {
  /* الشريط يخرج عن مجرى الصفحة فيأخذ المحتوى العرض كلّه.

     الإزاحة محور فيزيائي لا يقلبه dir، فالجهة تُحسم صراحةً لكل اتجاه:
     الشريط في جهة البداية، وهي اليمين في RTL فيخرج يميناً (موجب)،
     واليسار في LTR فيخرج يساراً (سالب). */
  .naf-sidebar {
    position: fixed;
    top: 0;
    bottom: 0;
    inset-inline-start: 0;
    z-index: 40;
    height: 100dvh;
    transform: translateX(100%);
    transition: transform 0.25s ease-out;
  }

  [dir='ltr'] .naf-sidebar {
    transform: translateX(-100%);
  }

  .naf-sidebar.is-open,
  [dir='ltr'] .naf-sidebar.is-open {
    transform: translateX(0);
    box-shadow: var(--shadow-xl);
  }

  .naf-menu-btn {
    display: grid;
  }

  .naf-backdrop.is-open {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 30;
    background: var(--overlay);
  }

  .naf-only-mobile { display: revert; }
  .naf-only-desktop { display: none; }

  .naf-content {
    padding: var(--space-4) var(--space-3);
  }
}

@media (width >= 900px) {
  /* فوق نقطة الانكسار: الشريط ثابت فلا درج ولا حجاب، والحساب يقول اسمه */
  .naf-account-text {
    display: block;
  }
}

/* ============================================================
   قلب الأيقونات في الاتجاه — الكتلتان من naf-icons.md «قواعد القلب».

   موضعها هنا لأن الهيكل نفسه يعرض `LogOut` في قائمة الحساب و`ChevronLeft`
   فاصلاً لفتات المسار، في المنصات الخمس. والقاعدة كانت مكتوبة في الخريطة
   ومطبَّقة في منصة واحدة من خمس — فكان سهم الخروج يشير إلى الخارج في
   التسويق وإلى الداخل في الأربع الباقية. الملف المسجَّل يطبّقها مرّة
   واحدة على الجميع.
   ============================================================ */

/* (أ) اسم واحد لا نظير له — الرسم لاتيني، فيُقلب في RTL */
[dir='rtl'] .lucide-send,
[dir='rtl'] .lucide-log-out,
[dir='rtl'] .lucide-log-in,
[dir='rtl'] .lucide-external-link,
[dir='rtl'] .lucide-reply { transform: scaleX(-1); }

/* (ب) اتجاه مزدوج — الاسم مختار بمظهره في RTL، فيُقلب في LTR */
[dir='ltr'] .lucide-arrow-left,
[dir='ltr'] .lucide-arrow-right,
[dir='ltr'] .lucide-chevron-left,
[dir='ltr'] .lucide-chevron-right { transform: scaleX(-1); }

/* شيفرون قائمة الحساب رأسيّ — لا يُقلب، ودورانه عند الفتح يبقى دورانه.
   القاعدة أعلاه لا تمسّه (`ChevronDown` ليست في الكتلتين)، وهذا توكيد. */

/* الحركة تتبع تفضيل القارئ */
@media (prefers-reduced-motion: reduce) {
  .naf-sidebar,
  .naf-account-chevron,
  .naf-nav-link,
  .naf-icon-btn,
  .naf-account,
  .naf-account-menu-item {
    transition: none;
  }
}
